<template><section><h1>Step 3 — Resume + Feedback + Save</h1><pre class="text-xs bg-gray-100 p-2">{{ s.recipe }}</pre><form @submit.prevent="save"><label for="fb-sweet">Sweet 0-100</label><UiNumber id="fb-sweet" label="Sweet 0-100" v-model="f.sweet" :min="0" :max="100" /><label for="fb-acid" class="mt-2 block">Acid 0-100</label><UiNumber id="fb-acid" label="Acid 0-100" v-model="f.acid" :min="0" :max="100" /><label for="fb-body" class="mt-2 block">Body 0-100</label><UiNumber id="fb-body" label="Body 0-100" v-model="f.body" :min="0" :max="100" /><button class="bg-black text-white px-4 py-2 mt-2">Save</button></form><p v-if="saved" class="text-sm text-green-700 mt-2">Saved locally — survives refresh.</p></section></template>
<script setup lang="ts">import { reactive, ref } from 'vue'; import { useBrewStore } from '../stores/brew'; import UiNumber from '../components/UiNumber.vue'; const s = useBrewStore(); const f = reactive({sweet:70,acid:70,body:70}); const saved = ref(false); function save(){ s.setFeedback({...f, saved_at: new Date().toISOString()}); saved.value = true }</script>
